#include "repository.h"
#include <cstdio>
int main(int argc,char **argv){QCoreApplication app(argc,argv);QCoreApplication::setApplicationVersion("1.0.0-windows");QFile input;input.open(stdin,QIODevice::ReadOnly);auto bytes=input.read(16*1024*1024+1);QJsonObject output;auto request=QJsonDocument::fromJson(bytes).object();auto path=request["database"].toString();QString error;if(bytes.size()>16*1024*1024||path.isEmpty())output={{"ok",false},{"error","Pedido inválido ou maior que 16 MiB"}};else {Repository repo(path);auto op=request["operation"].toString();if(!repo.error.isEmpty())output={{"ok",false},{"error",repo.error}};else if(op=="save"){auto data=request["record"].toObject();bool ok=repo.add(data["kind"].toString(),request["device"].toString(),data);output={{"ok",ok},{"error",repo.error}};}else if(op=="recent")output={{"ok",true},{"records",repo.recent(request["kind"].toString(),request["device"].toString(),3)}};else if(op=="feedback")output={{"ok",true},{"feedback",repo.feedback()}};else if(op=="import"){int count=repo.importFeedback(request["feedback"].toObject(),error);output={{"ok",count>=0},{"imported",count},{"error",error}};}else if(op=="references")output={{"ok",true},{"records",repo.references()}};else output={{"ok",false},{"error","Operação desconhecida"}};}auto result=QJsonDocument(output).toJson(QJsonDocument::Compact);fwrite(result.constData(),1,result.size(),stdout);return output["ok"].toBool()?0:1;}
